css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px 12px; margin-bottom: 8px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; margin-bottom: 3px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 12.5px; margin-bottom: 2px; line-height: 1.28;}
.mz .recuerda-idea strong{font-weight: 700;}
.mz .cal{border-collapse: collapse; margin: 0 auto;}
.mz .cal caption{font-size: 15px; font-weight: 700; margin-bottom: 4px; letter-spacing: 1px; text-transform: uppercase;}
.mz .cal th,.mz .cal td{border: 1.3px solid var(--bosque); width: 38px; height: 30px; text-align: center; font-size: 13px; font-family: sans-serif; font-weight: 600;}
.mz .cal th{background: #eee; font-size: 12px;}
.mz .cal td.vacio{background: #fafafa; border-color: #ccc;}
.mz .cal td.mk{background: #ddd;}
.mz .cal-wrap{display: flex; gap: 16px; align-items: flex-start;}
.mz .cal-preg{flex: 1;}
.mz .preg{font-size: 13px; font-weight: 700; margin-bottom: 7px; line-height: 1.3; display: flex; align-items: center; gap: 6px; flex-wrap: wrap;}
.mz .preg .resp{min-width: 80px; border-bottom: 1.5px solid var(--bosque); height: 18px; display: inline-block;}
.mz .respbox{width: 46px; height: 24px; border: 1.6px solid var(--bosque); border-radius: 5px; display: inline-block; vertical-align: middle;}
.mz .sec-grid{display: grid; grid-auto-flow: column; gap: 6px; justify-content: start; margin-bottom: 7px;}
.mz .sec-caja{min-width: 60px; height: 26px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 12.5px; font-weight: 700; padding: 0 4px;}
.mz .sec-caja.lleno{background: #eee;}
.mz .sec-caja.hueco{background: #fff;}
.mz .qlist{display: grid; grid-template-columns: 1fr 1fr; gap: 6px 22px;}
.mz .qrow{display: flex; align-items: center; gap: 6px; border: 1.5px solid var(--bosque); border-radius: 8px; padding: 5px 9px; font-size: 12.5px; font-weight: 700; flex-wrap: wrap;}
.mz .qrow .respbox{width: 70px; height: 22px; border: 1.5px solid var(--bosque); border-radius: 5px;}
.mz .problema{border: 1.6px solid var(--bosque); border-radius: 9px; padding: 7px 11px; margin-bottom: 8px; font-size: 13.5px; line-height: 1.35;}
.mz .op-line{display: flex; align-items: center; gap: 8px; margin-top: 6px; font-family: sans-serif; font-weight: 700; font-size: 13px; flex-wrap: wrap;}
.mz .op-line .sol{flex: 1; min-width: 100px; border-bottom: 1.4px solid var(--bosque); height: 16px;}
.mz .caja{width: 44px; height: 26px; border: 1.6px solid var(--bosque); border-radius: 6px; display: inline-block; vertical-align: middle;}
.mz .txt-flex{flex: 1 1 auto; min-width: 0;}
